effect.shader:
const int TAPS = 12;
void main(){
  vec2 uv = acScreenNorm;
  vec2 c = vec2(centerX, centerY);
  vec4 sum = vec4(0.0);
  for (int i = 0; i < TAPS; i++){
    float t = float(i) / float(TAPS - 1);
    float sc = 1.0 - amount * t * mixAmt;
    vec2 p = c + (uv - c) * sc;
    sum += texture2DCv(inputImg.texture, p);
  }
  gl_FragColor = sum / float(TAPS);
}
